
local factories = {main={}}
local descriptors = {main={}}
local native = {}
local function new_table() return {} end
local function pack(...) return select('#', ...), {...} end
local function bind(descriptor, upvalues)
    return factories[descriptor.group][descriptor.id](upvalues)
end
local function capture(descriptor, parent, registers, open, environment, destination, index, cell)
    local entries = descriptor[1]
    local count = #entries
    local upvalues = count > 0 and {}
    local closure = bind(descriptor, upvalues)
    setfenv(closure, environment)
    registers[destination] = closure
    local current, kind = descriptor, closure
    for position=1,count do
        current=entries[position]
        kind=current[2]
        index=current[1]
        if kind==0 then
            upvalues[position-1]=parent[index]
        elseif kind==1 then
            upvalues[position-1]=registers[index]
        elseif kind==2 then
            if not open then open={} end
            cell=open[index]
            if not cell then
                cell={[1]=index,[2]=registers}
                open[index]=cell
            end
            upvalues[position-1]=cell
        end
    end
    return current,entries,count,upvalues,kind,index,cell,open
end

